import {
  Card,
  CardContent,
  CardMedia,
  Typography,
  Grid,
  Container,
  Button,
  CircularProgress,
} from "@mui/material";

import { Link } from "react-router-dom";

import React from "react";
import { useEffect, useState } from "react";

import API from "../../services/api.js";

export default function Blog() {

  const [blogs, setBlogs] = useState([]);

  const [loading, setLoading] = useState(true);

  useEffect(() => {

    const fetchBlogs = async () => {

      try {

        const response = await API.get("/blogs");

        setBlogs(response.data);

      } catch (error) {

        console.log(error);

      } finally {

        setLoading(false);
      }
    };

    fetchBlogs();

  }, []);

  if (loading) {
    return (
      <Container sx={{ py: 5 }}>
        <CircularProgress />
      </Container>
    );
  }

  return (
    <Container sx={{ py: 5 }}>

      <Typography
        variant="h3"
        gutterBottom
        textAlign="center"
        fontWeight={700}
      >
        Latest Blogs
      </Typography>

      <Grid container spacing={4}>

        {blogs.map((blog) => (

          <Grid
            item
            xs={12}
            sm={6}
            md={4}
            key={blog._id}
          >

            <Card
              sx={{
                height: "100%",
                display: "flex",
                flexDirection: "column",
                borderRadius: 4,
                transition: "0.3s",
                "&:hover": {
                  transform: "translateY(-5px)",
                },
              }}
            >

              <CardMedia
                component="img"
                height="220"
                image={blog.image}
                alt={blog.title}
              />

              <CardContent sx={{ flexGrow: 1 }}>

                <Typography
                  variant="h5"
                  fontWeight={700}
                >
                  {blog.title}
                </Typography>

                <Typography
                  variant="body2"
                  color="text.secondary"
                  sx={{ mt: 1 }}
                >
                  {blog.content.slice(0, 100)}...
                </Typography>

              </CardContent>

              <Button
                component={Link}
                to={`/blog/${blog._id}`}
                variant="contained"
                sx={{
                  m: 2,
                  borderRadius: 3,
                }}
              >
                Read More
              </Button>

            </Card>

          </Grid>
        ))}
      </Grid>
    </Container>
  );
}
